INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S1-Q22$batch11$, 159, 1, 22, $batch11$Must Be True$batch11$, $batch11$Some moral virtues, such as honesty, tend to benefit one who has them; others, such as generosity, do not. A personal characteristic is not a moral virtue if it tends to be detrimental to other people.$batch11$, $batch11$If the statements above are true, which one of the following must also be true?$batch11$, $batch11$B$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$A person totally lacking in moral virtue will tend not to have characteristics that benefit others.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Being honest tends not to be detrimental to other people.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$A morally virtuous person tends to be a greater benefit to other people than a person who is not morally virtuous.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Being generous tends to be to one’s own detriment but not to the detriment of others.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$If a personal characteristic that one has tends to benefit others, then that personal characteristic is a moral virtue.$batch11$, $batch11$Reversed$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Honesty is a moral virtue. Generosity is a moral virtue. If a trait tends to harm other people, it is not a moral virtue.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Harms others → not a virtue. Contrapositive: virtue → doesn't harm others. Honesty is a virtue, so honesty doesn't tend to harm others.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Honesty tends not to harm other people.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Lacking virtue doesn't mean lacking traits that benefit others. Plenty of traits could help others without being virtues.$batch11$), ($batch11$B$batch11$, $batch11$Honesty is a moral virtue, and no virtue tends to harm others.$batch11$), ($batch11$C$batch11$, $batch11$Virtues avoid harming others. That doesn't mean they benefit others more than other traits.$batch11$), ($batch11$D$batch11$, $batch11$Generosity doesn't harm others, but we're only told it doesn't benefit its owner. "To one's own detriment" goes too far.$batch11$), ($batch11$E$batch11$, $batch11$Not harming others is required for a virtue. Benefiting others isn't enough to make one.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S1-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
